public sealed record ResolverSolicitudRequest(string Estado, decimal? ImporteConcedido);

app.MapPost("/api/solicitudes/{id:int}/resolucion", async (
    int id, ResolverSolicitudRequest request, AppDbContext db, TimeProvider time, CancellationToken ct) =>
{
    var solicitud = await db.Solicitudes.FirstOrDefaultAsync(s => s.Id == id, ct);
    if (solicitud is null)
    {
        return Results.NotFound();
    }

    if (solicitud.Estado != "EN_REVISION")
    {
        return Results.Conflict(new { error = "La solicitud no está en revisión." });
    }

    if (request.Estado is not ("CONCEDIDA" or "DENEGADA"))
    {
        return Results.BadRequest(new { error = "El estado final debe ser CONCEDIDA o DENEGADA." });
    }

    if (request.Estado == "CONCEDIDA")
    {
        if (request.ImporteConcedido is null or <= 0 || request.ImporteConcedido > solicitud.ImporteSolicitado)
        {
            return Results.BadRequest(new { error = "El importe debe ser mayor que 0 y no superar el solicitado." });
        }

        solicitud.ImporteConcedido = request.ImporteConcedido;
    }

    solicitud.Estado = request.Estado;
    solicitud.FechaResolucion = DateOnly.FromDateTime(time.GetUtcNow().UtcDateTime);
    await db.SaveChangesAsync(ct);
    return Results.NoContent();
});

Códigos: 404 si no existe, 409 si el estado actual no permite resolver, 400 si los datos son inválidos, 204 si todo va bien (o 200 con la solicitud actualizada).

Pruebas unitarias: resolución correcta como CONCEDIDA y como DENEGADA; solicitud inexistente (404); solicitud que no está EN_REVISION (409); importe cero, negativo, nulo o superior al solicitado (400); estado final no permitido (400). Se inyecta TimeProvider para fijar la fecha de resolución en los tests.
